<script setup lang="ts">
import { ArrowLeft, Truck, ShieldCheck, Package } from 'lucide-vue-next'
const parcels=ref([{name:'Sample parcel — small',grams:500},{name:'Sample parcel — medium',grams:2000},{name:'Sample parcel — large',grams:5000}])
const providers=['PostNord','DHL','Bring']
const quotes=reactive<Record<string,{price:string;days:string;verified:boolean}>>(Object.fromEntries([500,2000,5000].flatMap(weight=>['PostNord','DHL','Bring'].map(provider=>[provider+'-'+weight,{price:'',days:'',verified:false}]))))
const key=(provider:string,weight:number)=>provider+'-'+weight
const complete=computed(()=>Object.values(quotes).filter(q=>q.verified&&Number(q.price)>0).length)
useSeoMeta({title:'Shipping sandbox planner',robots:'noindex,nofollow'})
</script>
<template><main class="admin-shell"><header class="admin-topbar"><NorrliLogo compact/><NuxtLink to="/admin/commerce-acceptance" class="btn btn-secondary compact"><ArrowLeft :size="16"/> Acceptance</NuxtLink></header><section class="sp-wrap"><span class="eyebrow"><Truck :size="16"/> PHASE 6 · NON-TRANSACTIONAL PLANNER</span><h1>Shipping comparison sandbox</h1><p>Enter carrier quotations manually for scenario planning. Values here are local to this page and are never sent to a carrier, customer, or payment service. No carrier is represented as integrated or contracted.</p><div class="sp-warning"><ShieldCheck :size="20"/> Live order fulfillment, label purchases, and payments are disabled.</div><div class="sp-grid"><article v-for="parcel in parcels" :key="parcel.grams"><Package :size="23"/><h2>{{parcel.name}}</h2><p>Planning weight: {{parcel.grams}} g</p><div v-for="provider in providers" :key="provider" class="sp-row"><strong>{{provider}}</strong><label>Quoted cost (SEK)<input v-model="quotes[key(provider,parcel.grams)].price" type="number" min="0" step="0.01" placeholder="—"/></label><label>Transit days<input v-model="quotes[key(provider,parcel.grams)].days" type="number" min="1" max="90" placeholder="—"/></label><label class="sp-check"><input v-model="quotes[key(provider,parcel.grams)].verified" type="checkbox"/> Quote independently verified</label></div></article></div><p class="sp-footer">Verified planning entries this session: {{complete}}. Verify insurance, tracking, cut-off times, return labels and real supplier lead times separately before launch.</p></section></main></template>
